mapper.select:
SELECT * FROM sys_task_execution
WHERE tenant_id = #{tenantId}
  AND execution_key = #{executionKey}
  AND delete_flag = 0

mapper.update:
UPDATE sys_task_execution
SET lease_until = now() + make_interval(secs => #{leaseSeconds}::int),
    updated_at  = now()
WHERE tenant_id      = #{tenantId}
  AND execution_key  = #{executionKey}
  AND delete_flag    = 0
  AND status         = 'RUNNING'
  AND lease_owner    = #{leaseOwner}
  AND attempt_count  = #{expectedAttempt}
  AND lease_until > now()

UPDATE sys_task_execution
SET status      = CASE WHEN #{success} THEN 'SUCCESS' ELSE 'FAILED' END,
    finished_at = now(),
    last_error  = #{lastError},
    lease_until = NULL,
    updated_at  = now()
WHERE tenant_id      = #{tenantId}
  AND execution_key  = #{executionKey}
  AND delete_flag    = 0
  AND status         = 'RUNNING'
  AND lease_owner    = #{leaseOwner}
  AND attempt_count  = #{expectedAttempt}

mapper.select:
SELECT * FROM sys_task_execution
WHERE delete_flag = 0
  AND attempt_count < #{maxAttempts}
  AND (
        (status = 'RUNNING' AND lease_until < now())
        OR status = 'FAILED'
      )
ORDER BY updated_at
LIMIT #{limit}

mapper.update:
UPDATE sys_task_execution
SET attempt_count = #{maxAttempts},
    last_error    = #{reason},
    updated_at    = now()
WHERE tenant_id     = #{tenantId}
  AND execution_key = #{executionKey}
  AND delete_flag   = 0
  AND status        = #{expectedStatus}
  AND status       != 'SUCCESS'
  AND attempt_count = #{expectedAttempt}
  AND attempt_count < #{maxAttempts}
  AND (status = 'FAILED' OR lease_until < now())
